/* vendor.js: bundled utility library (unminified, mostly unused) */

/**
 * Utility function number 0. Normalizes a list of values, applies a transformation and returns a summary.
 */
function utilityFunction0(values, options) {
  var result = [];
  var settings = options || { factor: 1, offset: 0 };
  for (var index = 0; index < values.length; index++) {
    var current = values[index] * settings.factor + settings.offset;
    result.push(current);
  }
  return { count: result.length, total: result.reduce(function (a, b) { return a + b; }, 0) };
}

